import React from 'react'

export default function Card(props) {

    let option = props.options ?? {};
    let priceOptions = Object.keys(option);

    return (
        <div>
            <div>
                <div className="card mt-3 ml-3" style={{ "width": "18rem", "maxHeight": "400px" }}>
                    <img src= {props.imgScr} className="card-img-top" alt="..." />
                    <div className="card-body">
                        <h5 className="card-title">{props.foodName}</h5>

                        <div className='container w-100'>
                            <select className='m-2 h-100  bg-success rounded'>
                                {Array.from(Array(6), (e, i) => {
                                    return (
                                        <option key={i + 1} value={i + 1}> {i + 1} </option>
                                    )
                                })}
                            </select>
                            <select className='-2 h-100  bg-success rounded' >
                                {priceOptions.map((data) => (
                                    <option key={data} value={data}>{data}</option>
                                ))}
                            </select>
                            <div className='d-inline h-30 fs-6 m-3'>Total Price</div>
                        </div>

                    </div>
                </div>
            </div>

            <br></br>
        </div>
    )
}
